  "이 기억과 근거가 된 원본 기록을 영구히 지워요. 같은 원본에서 나온 다른 기억도 함께 지워져요.": "Permanently erases this memory and the source records behind it. Other memories from the same sources are erased too.",
  "영구 삭제": "Erase permanently",
  "사람 이름이나 메일 주소처럼 지우고 싶은 말을 넣으면, 그 말이 들어간 기억과 원본 기록을 모두 찾아 영구히 지워요. 먼저 몇 개인지 보여 드려요.": "Enter what you want gone, like a person's name or an email address. Arkism finds every memory and source record containing it and erases them permanently. You see the count first.",
  "지울 말 (이름·메일 주소 등)": "Text to erase (name, email address…)",
  "예: 홍길동, name@example.com": "e.g. Jane Doe, name@example.com",
  "너무 많아 일부만 셌어요. 지운 뒤 다시 찾아보세요.": "Too many to count all of them. Search again after erasing.",
  "조금 짧게 입력하세요.": "Make it a little shorter.",
  "두 글자 이상 입력하세요.": "Enter at least two characters.",
  "이 계정은 기억과 원본 기록을 찾을 수 없어요.": "This account can't search memories and source records.",
  "찾지 못했어요. 연결을 확인하고 다시 시도하세요.": "Couldn't search. Check the connection and try again.",
  "입력한 말이 달라 지우지 않았어요.": "The text didn't match, so nothing was erased.",
  "이 PC에서 ssh 접속이 비밀번호 없이(SSH 키로) 되면 바로 연결돼요. 포트가 다르면 주소 뒤에 :2222처럼 붙여요.": "Works right away if ssh to the server works from this PC without a password (with an SSH key). For another port, add it like :2222.",
  "서버에 연결해요. 평소 ssh로 접속하는 주소만 넣으면 돼요.": "Connect to a server. Just enter the address you normally use with ssh.",
  "SSH 주소": "SSH address",
  "user@서버주소": "user@server-address",
  "연결하는 중…": "Connecting…",
  "연결 끊김": "Disconnected",
  "다른 서버에 연결": "Connect to another server",
  "서버에 연결됨": "Connected to the server",
  "서버에 연결돼 있어요.": "Connected to the server.",
  "연결을 끊으면 다음에 앱을 켤 때 자동으로 다시 붙지 않아요.": "After disconnecting, the app won't reconnect automatically next time it starts.",
  "SSH 주소를 넣어 주세요.": "Enter the SSH address.",
  "서버 연결은 Arkism 앱에서만 돼요.": "Connecting to a server works only in the Arkism app.",
  "주소를 확인하세요. user@서버주소 또는 user@서버주소:포트 처럼 적어요.": "Check the address. Write it like user@server or user@server:port.",
  "이 PC에서 ssh 프로그램을 찾지 못했어요. OpenSSH(또는 Git for Windows)를 설치해 주세요.": "Couldn't find ssh on this PC. Install OpenSSH (or Git for Windows).",
  "SSH 로그인이 거부됐어요. 이 PC에서 ‘ssh 주소’가 비밀번호 없이(SSH 키로) 되는지 확인하세요.": "SSH login was refused. Check that ‘ssh address’ works on this PC without a password (with an SSH key).",
  "서버의 SSH 키가 예전과 달라요. 맞는 서버라면 known_hosts에서 옛 키를 지운 뒤 다시 연결하세요.": "The server's SSH key has changed. If it's the right server, remove the old key from known_hosts and connect again.",
  "서버에 닿지 못했어요. 주소·포트와 네트워크 연결을 확인하세요.": "Couldn't reach the server. Check the address, port and your network.",
  "서버에 로그인은 됐지만 Arkism이 설치돼 있지 않아요.": "Logged in to the server, but Arkism isn't installed there.",
  "서버의 Arkism이 오래돼서 이 연결 방식을 몰라요. 서버의 Arkism을 업데이트해 주세요.": "The server's Arkism is too old for this kind of connection. Update Arkism on the server.",
  "연결은 됐지만 서버의 Arkism을 열지 못했어요. 서버에서 Arkism이 켜져 있는지 확인하세요.": "Connected, but couldn't open the server's Arkism. Check that Arkism is running on the server.",
  "진단": "Diagnostics",
  "이 PC의 Arkism 연결·에이전트·수집 대기열·디스크를 점검해요.": "Checks this PC's Arkism connection, agents, capture queues and disk.",
  "문제": "Problem",
  "고치는 중…": "Fixing…",
  "점검하는 중…": "Checking…",
  "점검하지 못했어요.": "Couldn't run the check.",
  "점검": "Check",
  "예: 회사 고객 이름은 기억하지 마. 배포·테스트 규칙은 꼭 기억해.": "e.g. Don't remember client names. Always remember deploy and test rules.",
  "기억할 것에 대한 메모": "Note on what to remember",
  "메모를 저장했어요. 다음 수집부터 써요.": "Note saved. It applies from the next capture.",
  "무엇을 기억할지 메모": "What to remember",
  "Arkism이 기억을 고를 때 참고해요. 비밀값·개인정보 규칙보다 앞서지는 않아요.": "Arkism uses it when choosing memories. It never overrides the rules on secrets and personal data.",
  "에이전트 기억 가져오기": "Import agent memories",
  "CLAUDE.md, Claude Code 메모리, AGENTS.md, GEMINI.md의 규칙·사실을 검토 대기로 가져와요. 승인한 것만 쓰여요.": "Brings the rules and facts in CLAUDE.md, Claude Code memory, AGENTS.md and GEMINI.md into the review queue. Only what you approve is used.",
  "기억 파일을 읽지 못했어요.": "Couldn't read the memory files.",
  "새로 가져올 기억이 없어요.": "Nothing new to import.",
  "가져오는 중이에요.": "Importing…",
  "가져오지 못했어요. 잠시 뒤 다시 시도해 주세요.": "Couldn't import. Try again in a moment.",
  "문서 › Arkism Backups 폴더에 저장해요. 하루 한 번 자동으로도 백업해요(자동 백업은 최근 7개만 남겨요). 다른 PC로 옮길 때는 이 폴더를 복사하면 돼요.": "Saved to Documents › Arkism Backups. Arkism also backs up once a day on its own (keeping the last 7 automatic backups). To move to another PC, copy this folder.",
  "이 PC 모드에서는 워크플로우를 만들고 저장할 수 있어요. 실행과 $이름 호출은 서버에 연결했을 때 돼요.": "On this PC you can create and save workflows. Running them and $name calls work when connected to a server.",
  "Git 화면은 서버에 연결했을 때 써요. 서버의 저장소를 SSH로 읽어 커밋·PR·검사를 보여 줘요. 설정 › 고급에서 서버에 연결할 수 있어요.": "The Git view works when connected to a server: it reads the server's repositories over SSH to show commits, PRs and checks. Connect in Settings › Advanced.",
  "로그인할 때 Arkism 시작": "Start Arkism when you sign in",
  "창 없이 트레이에서 시작해 에이전트 대화를 계속 저장해요.": "Starts in the tray without a window and keeps saving your agent conversations.",
  "로그인할 때 Arkism이 트레이에서 시작해요.": "Arkism will start in the tray when you sign in.",
  "로그인할 때 시작하지 않아요. 앱이 꺼져 있으면 수집도 멈춰요.": "Arkism won't start when you sign in. Capture stops while the app is closed.",
  "시작 설정을 바꾸지 못했어요.": "Couldn't change the startup setting.",
  "검색 방식": "Search",
  "의미와 키워드로 찾아요. 이 PC의 Ollama가 기억을 벡터로 바꿔요.": "Searches by meaning and keywords. Ollama on this PC turns memories into vectors.",
  "키워드로 찾아요. Ollama를 설치하고 'ollama pull qwen3-embedding:0.6b'를 실행한 뒤 앱을 다시 열면 의미 검색이 켜져요.": "Searches by keywords. Install Ollama, run 'ollama pull qwen3-embedding:0.6b' and reopen the app to turn on meaning search.",
