  "디자인 시스템": "Design system",
  "제품별·목적별로 모아 둔 디자인 시스템이에요. 카드를 고르면 색·글꼴·쓰는 법을 봐요.": "Design systems grouped by product and purpose. Pick a card to see its colors, fonts and usage.",
