  "AI가 최근 기억과 후보를 보고 새 스킬을 찾는 중이에요…": "AI is looking through recent memories and candidates for new skills…",
  "(없음)": "(none)",
  "지금은 새 스킬로 만들 만한 반복 요청이 없어요.": "No repeated requests worth turning into a new skill right now.",
  "AI 답을 읽지 못했어요. 다시 해 주세요.": "Couldn't read the AI's answer. Please try again.",
  "이 스킬을 쓰던 에이전트는 더 이상 읽지 못해요. 스킬 › 휴지통에서 언제든 되돌릴 수 있어요.": "Agents that used these skills will no longer be able to read them. You can restore them anytime from Skills › Trash.",
  "취소": "Cancel",
