  "스킬 이름은 영문 소문자·숫자·하이픈만 써요.": "Skill names can only use lowercase letters, numbers and hyphens.",
  "스킬이 아니에요": "Not a skill",
  "하나로 합치면 두 스킬을 쓰던 에이전트가 모두 합친 스킬을 써요.": "After merging, agents that used either skill will use the merged one.",
  "사용 기록 없음": "No usage yet",
