  "누르면 이 이름을 남겨요": "Click to keep this name",
  "합치면 이렇게 돼요": "Here's what merging does",
  "합쳐서 미리 보기": "Merge and preview",
  "AI가 두 SKILL.md를 하나로 쓰는 중이에요…": "AI is combining the two SKILL.md files into one…",
  "합친 SKILL.md · 원본 저장소에 붙여 넣어 주세요": "Merged SKILL.md · paste it into the source repository",
  "다른 스킬이에요": "They're different skills",
  "AI가 두 SKILL.md를 하나로 써 줘요. 합치기 전에 결과를 보고 고칠 수 있어요.": "AI combines the two SKILL.md files into one. You can review and edit the result before merging.",
  "두 기억이 같은 말을 해요. 하나만 있어도 에이전트가 똑같이 알아요.": "Both memories say the same thing. Agents know just as much with only one of them.",
  "남길 기억이 더 자세해요. 다른 하나의 내용이 거기에 들어 있다고 봤어요.": "The memory to keep is more detailed. The other one's content appears to be included in it.",
  "새 기억이 예전 기억과 반대예요. 지금 생각은 새 기억이라고 봤어요.": "The new memory contradicts the old one. The new memory is taken as your current view.",
  "서로 다른 말을 하는 기억, 새 것으로 바꿀까요?": "These memories disagree. Replace with the new one?",
  "비슷한 기억 2개, 하나로 합칠까요?": "2 similar memories. Merge them into one?",
  "같은 내용을 다른 말로 적었어요": "The same content, worded differently",
  "서로 다른 말을 하고 있어요": "They say different things",
  "두 기억이 같은 뜻이에요. 하나만 남겨 두면 AI가 덜 헷갈려요.": "Both memories mean the same thing. Keeping just one makes the AI less confused.",
  "두 기억을 함께 따를 수 없어요. 지금 생각에 맞는 쪽만 남겨요.": "The two memories can't both be followed. Keep only the one that matches your current view.",
  "새 것": "New",
  "옛 것": "Old",
  "왜 제안했나요": "Why was this suggested?",
  "바꾸면 이렇게 돼요": "Here's what replacing does",
  "이력에서 언제든 다시 볼 수 있어요": "You can always see it again in history",
  "둘 다 두기": "Keep both",
  "둘 다 그대로 뒀어요. 같은 제안은 다시 하지 않아요.": "Kept both as they are. This won't be suggested again.",
  "반대로 남기기": "Keep the other one",
  "반대쪽 기억을 남겼어요. 다른 하나는 이력에 남아요.": "Kept the other memory. The remaining one stays in history.",
  "제안대로 합치기": "Merge as suggested",
  "제안대로 바꾸기": "Replace as suggested",
  "합쳤어요. 옛 기억은 이력에 남아요.": "Merged. The old memory stays in history.",
  "바꿨어요. 예전 기억은 이력에 남아요.": "Replaced. The old memory stays in history.",
  "어느 쪽을 골라도 지우지 않아요. 넘긴 기억은 기억 이력에 남아요.": "Whichever you choose, nothing is deleted. The memory you move aside stays in memory history.",
  "눌러서 저장·버리기를 바꾸고 한 번에 반영해요. 14일 동안 안 보면 저절로 사라져요.": "Click to toggle save/discard, then apply them all at once. Candidates you don't look at for 14 days disappear on their own.",
