  "프롬프트 보관함": "Prompt library",
  "자주 쓰는 이미지·슬라이드 프롬프트를 예시 이미지와 함께 모아 둬요. 모델과 카테고리로 골라 보고, 카드를 고르면 프롬프트를 복사할 수 있어요.": "Keep your go-to image and slide prompts together with example images. Filter by model and category, then pick a card to copy its prompt.",
