  "이 프롬프트로 만들기": "Create with this prompt",
  "쓰는 워크플로우가 없어서 채운 프롬프트를 복사했어요. 쓰는 워크플로우를 정하면 바로 맡길 수 있어요.": "No workflow is set, so the filled-in prompt was copied. Set a workflow to hand it off directly.",
