  "AI가 이름을 정하는 중이에요…": "AI is choosing a name…",
  "이미지·슬라이드 생성 프롬프트를 라이브러리에 저장한다. 아래 내용을 읽고 이름을 정하고, 비어 있는 칸만 채운다.": "Save an image/slide generation prompt to the library. Read the content below, choose a name, and fill in only the empty fields.",
  "답은 JSON 객체 하나만: {\"title\": \"내용이 드러나는 한국어 이름 30자 이내\", \"tags\": [\"카테고리 1~3개\"], \"negative\": \"프롬프트가 피하라고 한 것을 영어 쉼표 목록으로, 없으면 빈 문자열\", \"size\": \"프롬프트에 크기·비율이 있으면 1024×1536 꼴, 없으면 빈 문자열\"}": "Reply with a single JSON object only: {\"title\": \"a Korean name of up to 30 characters that reflects the content\", \"tags\": [\"1–3 categories\"], \"negative\": \"things the prompt says to avoid, as a comma-separated English list, or an empty string if none\", \"size\": \"if the prompt specifies a size or ratio, in the form 1024×1536; otherwise an empty string\"}",
  "(비어 있음)": "(empty)",
  "너는 이미지 프롬프트 라이브러리 정리 도우미다. 프롬프트를 읽고 저장 칸만 채운다.": "You are an assistant that organizes an image prompt library. Read the prompt and fill in only the save fields.",
  "기다리는 동안 프롬프트가 바뀌어 답을 쓰지 않았어요. 다시 눌러 주세요.": "The prompt changed while waiting, so the answer wasn't applied. Please try again.",
  "AI가 이름을 정하지 못했어요. 직접 넣어 주세요.": "AI couldn't choose a name. Please enter one yourself.",
  "AI가 이름과 빈 칸을 채웠어요. 맞게 고쳐서 저장하세요.": "AI filled in the name and empty fields. Review and adjust, then save.",
