  "서버의 Claude Code·Codex 설정을 1분마다 읽어 보여 줘요. 항목을 고르면 에이전트별로 켜고 끌 수 있어요.": "Reads the server's Claude Code and Codex settings every minute. Pick an item to turn it on or off per agent.",
