  "닫기": "Close",
  "이 서버는 로그인이 필요할 수 있어요. 로그인을 누르면 브라우저가 열리고, 허용하면 서버에 자동으로 적용돼요.": "This server may require sign-in. Click Sign in to open a browser; once you allow access, it's applied to the server automatically.",
