  "최대 몇 번 되돌아갈까요": "Max loop-backs",
  "넘으면 실행을 멈추고 이유를 남겨요. 성공한 노드 결과는 그대로 두고 대상부터 다시 돌아요.": "If exceeded, the run stops and records why. Successful node results are kept, and it reruns from the target.",
  "앞으로 가는 선이에요. 앞 노드로 이으면 되돌아가는 선이 돼요.": "This is a forward line. Connect to an earlier node to make a loop-back line.",
  "선 지우기": "Delete line",
  "이 노드만 실행": "Run this node only",
  "넣을 값 (비워도 돼요)": "Input value (optional)",
  "저장한 뒤에 실행할 수 있어요": "Save before running",
  "앞 단계는 건너뛰고 이 노드에만 값을 넣어 돌려요. 결과는 최근 실행에 남아요.": "Skips earlier steps and runs only this node with the given input. The result is kept in recent runs.",
  "단계 추가 — 그래프로 바뀌어요": "Add step — switches to graph",
  "단계가 하나라 간단히 보여요. 단계를 더하면 그래프 편집기로 바뀌어요.": "With one step it's shown simply. Add steps to switch to the graph editor.",
  "구조 검토 닫기": "Close structure review",
  "규칙 검사 (코드)": "Rule checks (code)",
  "AI 제안": "AI suggestions",
  "AI가 그래프를 읽는 중…": "AI is reading the graph…",
  "AI 제안 받기": "Get AI suggestions",
  "토큰을 줄일 칸, 순서 문제, 멈추는 조건을 짚어 줘요. 실행할 때는 검토하지 않아요.": "Points out blocks that could use fewer tokens, ordering issues, and stop conditions. Not reviewed at run time.",
  "남은 제안이 없어요.": "No suggestions left.",
  "제안": "Suggestions",
  "무시": "Dismiss",
  "적용했어요. 저장하기 전까지는 되돌리기로 취소할 수 있어요.": "Applied. You can undo this until you save.",
  "그 노드나 선이 바뀌어 다시 받아야 해요": "That node or edge has changed, so fetch suggestions again",
  "바뀐 그래프로 다시 받기": "Fetch again for the updated graph",
  "[적용]을 누르면 그래프가 바로 바뀌고, 나머지 제안은 그대로 남아요. 실행 기록이 쌓이면 자주 다시 도는 노드도 짚어요.": "Click [Apply] to change the graph right away; the other suggestions stay. Once runs pile up, nodes that rerun often are flagged too.",
