  "이 PC의 Arkism을 쓰고 있어요": "Using Arkism on this PC",
  "기억은 이 PC에만 저장돼요. 서버의 Arkism을 쓰려면 서버에 연결하세요.": "Memories are stored only on this PC. To use Arkism on a server, connect to the server.",
  "로그인됨": "Signed in",
  "로그아웃하면 이 PC에 저장된 로그인 정보를 지워요.": "Signing out removes the sign-in info stored on this PC.",
  "로그아웃": "Sign out",
  "이 PC의 Arkism으로 돌아가기": "Go back to Arkism on this PC",
  "서버 연결을 끝내고 이 PC에 저장된 기억을 써요. 서버의 기억은 그대로 남아요.": "Ends the server connection and uses memories stored on this PC. Memories on the server stay as they are.",
  "이 PC에서 쓰기": "Use on this PC",
  "다른 계정에서 내보낸 파일이에요. 그 계정으로 로그인한 뒤 가져와 주세요.": "This file was exported from a different account. Sign in to that account, then import it.",
  "다른 작업 범위에서 내보낸 파일이에요. 설정 › 고급 › 연결의 범위를 맞춰 주세요.": "This file was exported from a different workspace scope. Match the scope in Settings › Advanced › Connection.",
  "가져오지 못했어요. Arkism에서 내보낸 파일인지 확인해 주세요. 기존 설정은 그대로예요.": "Couldn't import. Make sure the file was exported from Arkism. Your existing settings are unchanged.",
  "PC 설정 옮기기": "Move PC settings",
  "화면·정렬·분류 설정을 파일로 옮겨요. 로그인 정보와 기억·스킬 제안은 포함하지 않아요.": "Moves display, sorting, and categorization settings via a file. Sign-in info, memories, and skill suggestions aren't included.",
  "PC 설정 내보내기": "Export PC settings",
  "설정 파일을 저장했어요. 다른 PC의 설정 › 고급에서 가져오세요.": "Settings file saved. Import it from Settings › Advanced on the other PC.",
  "설정 파일을 만들지 못했어요. 기존 설정은 그대로예요.": "Couldn't create the settings file. Your existing settings are unchanged.",
  "PC 설정 가져오기": "Import PC settings",
  "설정을 가져왔어요. 화면을 다시 불러와요.": "Settings imported. Reloading the window.",
  "기억 정리 설정 옮기기": "Move memory cleanup settings",
  "‘유지’로 표시한 기억과 정리 설정을 옮겨요. 같은 계정·같은 범위에서만 가져올 수 있어요. 로그인 정보와 기억 본문은 포함하지 않아요.": "Moves memories marked ‘Keep’ and cleanup settings. Can only be imported into the same account and scope. Sign-in info and memory content aren't included.",
  "기억 정리 설정 내보내기": "Export memory cleanup settings",
  "기억 정리 설정을 저장했어요. 같은 계정으로 로그인한 앱의 설정 › 고급에서 가져오세요.": "Memory cleanup settings saved. Import them from Settings › Advanced in an app signed in to the same account.",
  "기억 정리 설정을 내보내지 못했어요. 로그인과 연결 상태를 확인해 주세요.": "Couldn't export memory cleanup settings. Check your sign-in and connection.",
  "기억 정리 설정 가져오기": "Import memory cleanup settings",
  "스킬 제안 옮기기": "Move skill suggestions",
  "새 스킬 제안 초안과 숨긴 제안을 옮겨요. 같은 계정·같은 범위에서만 가져올 수 있어요. 초안 본문이 들어 있으니 다른 사람과 공유하지 마세요.": "Moves new skill suggestion drafts and hidden suggestions. Can only be imported into the same account and scope. Contains draft content, so don't share it with others.",
  "스킬 제안 내보내기": "Export skill suggestions",
  "스킬 제안을 저장했어요. 같은 계정으로 로그인한 앱의 설정 › 고급에서 가져오세요.": "Skill suggestions saved. Import them from Settings › Advanced in an app signed in to the same account.",
  "스킬 제안을 내보내지 못했어요. 로그인과 연결 상태를 확인해 주세요.": "Couldn't export skill suggestions. Check your sign-in and connection.",
  "스킬 제안 가져오기": "Import skill suggestions",
  "수집": "Capture",
  "멈추거나 뺀 폴더에서는 Arkism이 대화를 저장하지도, 기억을 넣지도 않아요. 저장소에 .arkism-ignore 파일을 두어도 같아요.": "In paused or excluded folders, Arkism neither saves conversations nor injects memories. Placing a .arkism-ignore file in a repository does the same.",
