  "데이터": "Data",
  "이 PC에 저장된 기억·세션·스킬 기록을 백업하고 되돌려요. 백업 폴더에는 모든 기억이 그대로 들어 있으니 안전한 곳에 두세요.": "Back up and restore memories, sessions, and skill records stored on this PC. The backup folder contains all memories as-is, so keep it somewhere safe.",
