  "되돌렸어요.": "Restored.",
  "지금 백업": "Back up now",
  "문서 › Arkism Backups 폴더에 저장해요. 다른 PC로 옮길 때도 이 폴더를 복사하면 돼요.": "Saved to Documents › Arkism Backups. To move to another PC, just copy this folder.",
  "백업하는 중이에요.": "Backing up.",
