  "모든 데이터 지우기": "Delete all data",
  "이 PC의 기억·세션·스킬 기록·설정 토큰과 보내기 전 수집 대기열을 지워요. 백업 폴더와 에이전트 자체 파일은 남아요.": "Deletes memories, sessions, skill records, settings tokens, and the unsent capture queue on this PC. The backup folder and the agents' own files remain.",
