  "중복": "Duplicates",
  "휴지통이 비어 있어요.": "The trash is empty.",
  "60일 동안 안 쓴 스킬이 없어요.": "No skills unused for 60 days.",
  "같은 이름으로 여러 곳에 있는 스킬이 없어요.": "No skills share a name across several places.",
  "60일 동안 한 번도 쓰이지 않았어요. 휴지통에서 언제든 되돌릴 수 있어요.": "Not used once in 60 days. You can restore them from the trash anytime.",
  "왼쪽에서 중복된 스킬을 골라요.": "Pick a duplicated skill on the left.",
  "에이전트마다 다른 쪽을 읽을 수 있어요. 한 곳을 원본으로 두고, 다른 쪽은 지우거나 에이전트에서 빼 주세요.": "Each agent may read a different copy. Keep one as the original, and delete the others or remove them from agents.",
