  "서버에 연결해 쓰는 동안에는 서버가 정한 모델을 써요. 이 PC의 Arkism으로 돌아가면 여기서 바꿀 수 있어요.": "While connected to a server, the server's chosen model is used. Go back to Arkism on this PC to change it here.",
  "의미로 기억을 찾을 때 써요. 자동은 이 PC의 Ollama에 모델이 있을 때만 켜요. 끄면 키워드로만 찾아요.": "Used to find memories by meaning. Auto turns on only when this PC's Ollama has the model. Off = keyword search only.",
