  "한도": "Limits",
  "게이트웨이가 모델마다 지켜요. 넘치면 그룹은 다음 모델로 넘기고, 단일 모델은 429와 Retry-After로 돌려보내요. 비우거나 0이면 제한이 없어요.": "The gateway enforces these per model. When exceeded, a group falls back to the next model and a single model returns 429 with Retry-After. Blank or 0 = no limit.",
