  "설정됨": "Set",
  "Claude Code·Codex가 모델 중계기(:8099)를 거칠 때 쓰는 열쇠예요. 다시 만들면 에이전트 설정에 새 토큰을 넣고, 중계기를 다시 켜면 예전 토큰은 막혀요.": "The key Claude Code and Codex use to go through the model gateway (:8099). Making a new one puts it in the agents' settings; once the gateway restarts, the old one stops working.",
  "토큰이 없어서 모델 중계기(:8099)를 거치는 요청이 막혀요. 다시 만들면 연결된 에이전트 설정에 바로 넣어요.": "There's no token, so requests through the model gateway (:8099) are blocked. Making one puts it straight into the connected agents' settings.",
  "토큰 파일이 깨졌거나 다른 사용자도 읽을 수 있게 열려 있어요. 다시 만들면 고쳐져요.": "The token file is damaged or readable by other users. Making a new one fixes it.",
  "모델 중계기": "Model gateway",
  "중계기 토큰을 다시 만들까요? 에이전트 설정에 새 토큰을 넣어요.": "Make a new gateway token? It goes into the agents' settings.",
  "새 토큰을 만들고 에이전트 설정에 넣었어요. 중계기를 다시 켜면 예전 토큰은 막혀요.": "Made a new token and put it in the agents' settings. The old one stops working once the gateway restarts.",
  "새 토큰을 만들었어요. 에이전트 설정에는 못 넣었어요 — 진단에서 고치기를 눌러 주세요.": "Made a new token, but couldn't put it in the agents' settings — press Fix under Diagnostics.",
  "토큰을 만들지 못했어요.": "Couldn't make the token.",
  "중계기 토큰": "Gateway token",
  "확인하지 못했어요": "Couldn't check",
  "다시 만들기": "Make new",
  "지금은 ARKISM_GATEWAY_TOKEN 환경 변수의 값을 써요.": "Right now the ARKISM_GATEWAY_TOKEN environment variable is used.",
  "토큰 다시 만들기": "Make a new token",
  "중계기 토큰이 없어요. 지금은 Claude Code·Codex 요청이 모델 라우팅을 거치지 못해요.": "There's no gateway token. Claude Code and Codex requests can't go through model routing right now.",
  "중계기 토큰 파일에 문제가 있어요. 지금은 Claude Code·Codex 요청이 모델 라우팅을 거치지 못해요.": "The gateway token file has a problem. Claude Code and Codex requests can't go through model routing right now.",
  "갈래 작업": "Fork",
  "짧은 질의": "Quick query",
  "대화 압축": "Compaction",
  "보조 작업": "Auxiliary",
  "곁가지 답": "Side reply",
  "본대화": "Main",
  "Claude Code 호출": "Claude Code calls",
  "본대화와 부속 호출을 따로 세요": "Main and side calls counted apart",
  "부속 호출": "Side calls",
  "부속 호출은 Claude Code가 제목·요약·대화 압축 같은 일로 따로 보내는 호출이에요. 비용은 공개 가격으로 셈한 추정이에요.": "Side calls are the extra calls Claude Code makes for titles, summaries, compaction and the like. Costs are estimates from public prices.",
  "최근 턴": "Recent turns"
