  "작성 중인 페르소나를 완성한다. 쓴 사람의 의도와 이미 쓴 문장은 살리고, 빈 칸은 채우고, 지시는 역할·말투·꼭 지킬 것·하지 말 것이 드러나게 \"너는 ○○다.\"로 시작하는 짧은 번호 목록으로 정리한다. 답의 키는 name, role, instructions만 쓴다.\n\n이름: {0}\n한 줄 설명: {1}\n지시:\n{2}": "Complete the persona being written. Keep the author's intent and any sentences already written, fill in empty fields, and organize the instructions as a short numbered list that starts with \"You are ○○.\" and makes clear the role, tone, must-dos, and don'ts. Use only the keys name, role, and instructions in the answer.\n\nName: {0}\nOne-line description: {1}\nInstructions:\n{2}",
